{
  "candidate_edge_types": [
    {
      "name": "REPEATS_MONITORING_ACTION_WHILE_AWAITING_MILESTONE",
      "definition": "A subsequent execution action repeats an earlier monitoring operation because the previous observation did not yet contain the awaited state change or progress milestone, so the agent keeps the long-running process under observation.",
      "source_description": "An observation produced by a monitoring action that still shows the awaited progress milestone or state change has not yet occurred.",
      "target_description": "A subsequent monitoring action of the same kind, re-issued to continue awaiting the milestone."
    },
    {
      "name": "DERIVES_TIMELINE_ESTIMATE_FROM_OBSERVED_PROGRESS",
      "definition": "An agent derives an expected time or completion horizon for an ongoing long-running process from progress markers contained in an earlier observation, with no direct corrective action taken.",
      "source_description": "An observation containing measurable progress markers of an ongoing process (e.g., iteration counter, timestamp, loss value).",
      "target_description": "An agent reasoning or planning event that estimates when a future milestone or process completion will occur."
    },
    {
      "name": "OBSERVATION_CONFIRMS_PRIOR_PREDICTION",
      "definition": "A later observation validates an expectation the agent had previously formed about an upcoming execution milestone or process state, confirming that the predicted event actually occurred.",
      "source_description": "An earlier agent expectation or prediction about an upcoming execution milestone or process state.",
      "target_description": "A later observation showing the anticipated milestone or state change actually occurred, matching the earlier expectation."
    },
    {
      "name": "WAITS_FOR_IN_PROGRESS_ACTION_TO_COMPLETE",
      "definition": "An agent defers any new operation and instead waits for the currently running operation to finish after an observation indicates the action is still in progress and has produced no output yet.",
      "source_description": "An observation indicating that a previously issued action is still executing and has not yet produced its result.",
      "target_description": "A subsequent agent decision or action that waits for or re-checks the in-progress operation without starting a new independent task."
    }
  ]
}

